mapper.select:
select id, username, (state = 'ACTIVE') as enabled, auth_version
from pep_platform.app_user
where id = #{id}

select id, username, (state = 'ACTIVE') as enabled, auth_version
from pep_platform.app_user
where username = #{username}

mapper.insert:
insert into pep_platform.role_permission (role_id, permission_code)
select id, #{permission} from pep_platform.role where code = #{roleCode}
on conflict do nothing

mapper.update:
update pep_platform.app_user
set password_hash = #{passwordHash}, auth_version = auth_version + 1, updated_at = now()
where id = #{id}
